    #[test]
    fn sequence_shadow_budget_stops_publish_no_partial_metrics() {
        let edges = [(0, 0, 7_500), (1, 1, 7_500)];
        let cases = [
            (
                SequenceRelationShadowLimits {
                    interval_items: 0,
                    ..sequence_test_limits()
                },
                SequenceRelationShadowStopReason::IntervalItemLimit,
            ),
            (
                SequenceRelationShadowLimits {
                    fenwick_ops: 0,
                    ..sequence_test_limits()
                },
                SequenceRelationShadowStopReason::FenwickOperationLimit,
            ),
            (
                SequenceRelationShadowLimits {
                    exclusion_runs: 0,
                    ..sequence_test_limits()
                },
                SequenceRelationShadowStopReason::ExclusionRunLimit,
            ),
            (
                SequenceRelationShadowLimits {
                    predecessor_items: 0,
                    ..sequence_test_limits()
                },
                SequenceRelationShadowStopReason::PredecessorItemLimit,
            ),
            (
                SequenceRelationShadowLimits {
                    estimated_bytes: 0,
                    ..sequence_test_limits()
                },
                SequenceRelationShadowStopReason::EstimatedByteLimit,
            ),
        ];
        for (limits, expected) in cases {
            let reason =
                sequence_test_analysis(&edges, &[], &[], &[], limits).expect_err("budget stops");
            assert_eq!(reason, expected);
            assert_eq!(
                stopped_sequence_relation_metrics(reason),
                SequenceRelationShadowMetrics {
                    complete: false,
                    stop_reason: Some(expected),
                    ..SequenceRelationShadowMetrics::default()
                }
            );
        }

        let mut collector = SequenceRelationShadowCollector::new(1, 1).expect("collector");
        let reason = collector
            .record_edge(
                SequenceRelationEdge {
                    interval: PairedInterval {
                        pair_index: 0,
                        interval_index: 0,
                    },
                    old_candidate: 0,
                    new_candidate: 0,
                    old_ordinal: 0,
                    new_ordinal: 0,
                    score: 7_500,
                },
                0,
            )
            .expect_err("edge budget stops");
        assert_eq!(reason, SequenceRelationShadowStopReason::EdgeItemLimit);
        assert_eq!(stopped_sequence_relation_metrics(reason).qualified_edges, 0);
    }

    #[test]
    fn paired_near_veto_primary_reasons_are_disjoint() {
        let tied = CandidateNearRelation {
            best_score: 7_500,
            second_score: 7_500,
            best_partner: Some(0),
            best_scope: None,
        };
        let insufficient = CandidateNearRelation {
            best_score: 7_500,
            second_score: 7_001,
            best_partner: Some(0),
            best_scope: None,
        };
        let disqualifying = CandidateNearRelation {
            best_score: 7_500,
            second_score: 7_000,
            best_partner: None,
            best_scope: None,
        };
        let unique = CandidateNearRelation {
            best_score: 7_500,
            second_score: 6_000,
            best_partner: Some(0),
            best_scope: None,
        };
        let reciprocal_failure = [CandidateNearRelation {
            best_score: 7_500,
            second_score: 6_000,
            best_partner: Some(1),
            best_scope: None,
        }];
        let empty = HashSet::new();
        assert_eq!(
            primary_near_veto_reason(0, tied, &[unique], true, &empty, &empty),
            Some(NearVetoReason::TiedBest)
        );
        assert_eq!(
            primary_near_veto_reason(0, insufficient, &[unique], true, &empty, &empty),
            Some(NearVetoReason::InsufficientMargin)
        );
        assert_eq!(
            primary_near_veto_reason(0, disqualifying, &[unique], true, &empty, &empty),
            Some(NearVetoReason::DisqualifyingCompetitor)
        );
        assert_eq!(
            primary_near_veto_reason(0, unique, &reciprocal_failure, true, &empty, &empty,),
            Some(NearVetoReason::ReciprocalFailure)
        );
        assert_eq!(
            primary_near_veto_reason(
                0,
                unique,
                &[unique],
                true,
                &[(0, 0)].into_iter().collect(),
                &empty,
            ),
            Some(NearVetoReason::CrossingRelation)
        );
        assert_eq!(
            primary_near_veto_reason(
                0,
                unique,
                &[unique],
                true,
                &empty,
                &[(0, 0)].into_iter().collect(),
            ),
            Some(NearVetoReason::FragmentCompletion)
        );
        assert_eq!(
            primary_near_veto_reason(
                0,
                CandidateNearRelation {
                    best_score: 6_999,
                    ..CandidateNearRelation::default()
                },
                &[],
                true,
                &empty,
                &empty,
            ),
            None
        );
    }

    fn topology_test_block(id: u64, role: BlockRole) -> BlockText {
        let mut block = collection_test_block(id, "x", Some(Vec::new()));
        block.role = role;
        block
    }

    #[allow(clippy::too_many_arguments)]
    fn topology_test_batch(
        old_blocks: &[BlockText],
        new_blocks: &[BlockText],
        old_intervals: &[Option<TrustedRunInterval>],
        new_intervals: &[Option<TrustedRunInterval>],
        old_occurrences: &[SentenceOccurrence],
        new_occurrences: &[SentenceOccurrence],
        main_anchors: &[ExactAnchor],
        limits: SegmentTopologyShadowLimits,
    ) -> (
        RecoveryWatchSegmentTopologyDiagnostics,
        RecoveryWatchSegmentTopologyShadow,
    ) {
        let old_side = SidePlan::inspect("old topology test", old_blocks)
            .expect("old blocks are valid")
            .materialize()
            .expect("old side materializes");
        let new_side = SidePlan::inspect("new topology test", new_blocks)
            .expect("new blocks are valid")
            .materialize()
            .expect("new side materializes");
        let old_stream_indices =
            trusted_stream_plan_indices(old_intervals).expect("old stream plans are valid");
        let new_stream_indices =
            trusted_stream_plan_indices(new_intervals).expect("new stream plans are valid");
        let old_segments = collect_recovery_segments(old_occurrences, 1, 100)
            .expect("old segment collection succeeds");
        let new_segments = collect_recovery_segments(new_occurrences, 1, 100)
            .expect("new segment collection succeeds");
        let old_index = old_segments
            .iter()
            .position(|segment| segment.unit_count == 2)
            .expect("old target segment exists");
        let new_index = new_segments
            .iter()
            .position(|segment| segment.unit_count == 2)
            .expect("new target segment exists");
        let (diagnostics, shadows) = analyze_source_range_topology_batch(
            &old_segments,
            &new_segments,
            &[(old_index, new_index)],
            0,
            Some(SegmentTopologyProjectionContext {
                main_anchors,
                old: SegmentTopologyProjectionSide {
                    side: &old_side,
                    trusted_intervals: old_intervals,
                    stream_indices: &old_stream_indices,
                    occurrences: old_occurrences,
                },
                new: SegmentTopologyProjectionSide {
                    side: &new_side,
                    trusted_intervals: new_intervals,
                    stream_indices: &new_stream_indices,
                    occurrences: new_occurrences,
                },
            }),
            limits,
        );
        let shadow = shadows.get(&(old_index, new_index)).cloned().unwrap_or(
            RecoveryWatchSegmentTopologyShadow::Stopped(
                diagnostics
                    .stop_reason
                    .unwrap_or(SegmentTopologyShadowStopReason::ProjectionUnavailable),
            ),
        );
        (diagnostics, shadow)
    }

