        let occurrences = (0..=MAX_RECOVERY_WATCH_RETAINED_OCCURRENCES)
            .map(|ordinal| positioned_occurrence("Repeated overlay.", ordinal as u64, ordinal, 0))
            .collect::<Vec<_>>();
        let mut watch = watch_state();
