    #[test]
    fn length_aware_local_fragment_shadow_preserves_fixed_retained_order() {
        let old = vec![
            local_fragment_parent("abcdefghijklmnopqrst tail", 1, 1),
            local_fragment_parent("short middle tail", 2, 2),
        ];
        let new = vec![
            local_fragment_parent("short middle tail", 3, 3),
            local_fragment_parent("abcdefghijklmnopqrst tail", 4, 4),
        ];
        let metrics = length_aware_analysis_metrics(old, new, 2, length_aware_limits());
        assert!(metrics.complete, "{:?}", metrics.stop_reason);
        assert_eq!(metrics.missing_retained_pairs, 0);
        assert_eq!(metrics.extra_retained_pairs, 0);
        assert_eq!(metrics.order_mismatches, 0);
        assert_eq!(
            metrics.fixed_exact_retained_pairs,
            metrics.length_aware_exact_retained_pairs
        );
        assert!(metrics.fixed_distinct_keys > 0);
        assert!(metrics.parent_distinct_keys > 0);
        assert!(metrics.posting_capacity_items >= metrics.fixed_posting_items);
        assert!(metrics.estimated_capacity_bytes >= metrics.estimated_logical_bytes);
        assert!(metrics.compared_queries > 0);
    }

    #[test]
    fn global_length_aware_shadow_matches_parent_scoped_results_with_fewer_queries() {
        let documents = || {
            (
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 1, 1)],
                vec![
                    local_fragment_parent("abcdefghijklmnopqrst tail", 2, 2),
                    local_fragment_parent("abcdefghijklmnopqrst tail", 3, 3),
                ],
            )
        };
        let (old, new) = documents();
        let parent_scoped = length_aware_analysis_metrics(old, new, 8, length_aware_limits());
        let (old, new) = documents();
        let global = global_length_aware_analysis_metrics(old, new, 8, length_aware_limits());
        assert!(global.complete, "{:?}", global.stop_reason);
        assert_eq!(global.missing_pre_recheck_candidates, 0);
        assert_eq!(global.extra_pre_recheck_candidates, 0);
        assert_eq!(global.pre_recheck_order_mismatches, 0);
        assert_eq!(global.missing_retained_pairs, 0);
        assert_eq!(global.extra_retained_pairs, 0);
        assert_eq!(global.order_mismatches, 0);
        assert_eq!(
            global.fixed_pre_recheck_candidates,
            parent_scoped.fixed_pre_recheck_candidates
        );
        assert_eq!(
            global.length_aware_pre_recheck_candidates,
            parent_scoped.length_aware_pre_recheck_candidates
        );
        assert_eq!(
            global.fixed_exact_retained_pairs,
            parent_scoped.fixed_exact_retained_pairs
        );
        assert_eq!(
            global.length_aware_exact_retained_pairs,
            parent_scoped.length_aware_exact_retained_pairs
        );
        assert_eq!(global.global_queries, global.compared_queries);
        assert_eq!(
            global.work.queries_examined,
            global.parent_admission_queries + global.global_queries
        );
        assert!(global.projected_parent_scoped_queries > global.global_queries);
        assert_eq!(
            global.raw_signature_hits,
            global.parent_admissible_hits + global.parent_rejected_hits
        );
        assert_eq!(
            global.parent_admissible_hits,
            global.fixed_pre_recheck_candidates
                + global.length_aware_pre_recheck_candidates
                + global.duplicate_candidate_occurrences
        );
    }

    #[test]
    fn local_fragment_recheck_reuse_halves_identical_candidate_rechecks() {
        let documents = || {
            (
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 1, 1)],
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 2, 2)],
            )
        };
        let (old, new) = documents();
        let global = global_length_aware_analysis_metrics(old, new, 8, length_aware_limits());
        let (old, new) = documents();
        let reuse = recheck_reuse_analysis_metrics(old, new, 8, length_aware_limits());
        assert!(reuse.complete, "{:?}", reuse.stop_reason);
        assert_eq!(reuse.fixed_only_pre_recheck_candidates, 0);
        assert_eq!(reuse.length_aware_only_pre_recheck_candidates, 0);
        assert_eq!(
            reuse.shared_pre_recheck_candidates,
            reuse.unique_recheck_pairs
        );
        assert_eq!(
            reuse.projected_duplicate_recheck_pairs,
            reuse.unique_recheck_pairs * 2
        );
        assert_eq!(reuse.avoided_recheck_pairs, reuse.unique_recheck_pairs);
        assert_eq!(
            reuse.actual_recheck_comparisons,
            reuse.avoided_recheck_comparisons
        );
        assert_eq!(
            reuse.projected_duplicate_recheck_comparisons,
            reuse.actual_recheck_comparisons * 2
        );
        assert_eq!(
            reuse.work.exact_recheck_pairs_examined,
            reuse.unique_recheck_pairs
        );
        assert_eq!(
            reuse.work.exact_recheck_comparisons_examined,
            reuse.actual_recheck_comparisons
        );
        assert_eq!(
            reuse.fixed_pre_recheck_fingerprint,
            global.fixed_pre_recheck_fingerprint
        );
        assert_eq!(
            reuse.length_aware_pre_recheck_fingerprint,
            global.length_aware_pre_recheck_fingerprint
        );
        assert_eq!(
            reuse.fixed_retained_fingerprint,
            global.fixed_retained_fingerprint
        );
        assert_eq!(
            reuse.length_aware_retained_fingerprint,
            global.length_aware_retained_fingerprint
        );
        assert_eq!(
            reuse.work.enumeration_examined,
            reuse.old_fragments + reuse.new_fragments
        );
        assert_eq!(
            reuse.work.queries_examined,
            reuse.parent_admission_queries + reuse.global_queries
        );
        assert_eq!(reuse.compared_queries, reuse.global_queries);
    }

    #[test]
    fn length_aware_recheck_skips_fixed_only_candidates_and_preserves_fingerprints() {
        let documents = || {
            (
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 1, 1)],
                vec![local_fragment_parent("abXXXXXXXXXXXXXXXXXX tail", 2, 2)],
            )
        };
        let (old, new) = documents();
        let reuse = recheck_reuse_analysis_metrics(old, new, 8, length_aware_limits());
        let (old, new) = documents();
        let length_aware =
            length_aware_recheck_analysis_metrics(old, new, 8, length_aware_limits());
        assert!(reuse.complete, "{:?}", reuse.stop_reason);
        assert!(length_aware.complete, "{:?}", length_aware.stop_reason);
        assert!(reuse.fixed_only_pre_recheck_candidates > 0);
        assert_eq!(reuse.work_attribution.fixed_only.accepted_pairs, 0);
        assert_eq!(
            length_aware.pre_recheck_candidates,
            reuse.length_aware_pre_recheck_candidates
        );
        assert_eq!(
            length_aware.recheck_pairs,
            length_aware.pre_recheck_candidates
        );
        assert!(length_aware.recheck_pairs < reuse.unique_recheck_pairs);
        assert_eq!(
            length_aware.pre_recheck_fingerprint,
            reuse.length_aware_pre_recheck_fingerprint
        );
        assert_eq!(
            length_aware.retained_fingerprint,
            reuse.length_aware_retained_fingerprint
        );
        assert_eq!(
            length_aware.retained_fingerprint,
            reuse.fixed_retained_fingerprint
        );
        assert_eq!(
            length_aware.work.candidate_union_examined,
            reuse.fixed_pre_recheck_candidates + reuse.length_aware_pre_recheck_candidates,
            "candidate-union work truthfully includes fixed and length-aware construction"
        );
    }

