    #[test]
    fn flat_exact_classes_match_exact_edges_exhaustively() {
        let sequence = |length: usize, bits: usize| {
            (0..length)
                .map(|offset| {
                    SentenceEvidenceToken::Scalar(if bits & (1 << offset) == 0 { 'a' } else { 'b' })
                })
                .collect::<Vec<_>>()
        };
        for old_len in 1..=5 {
            for new_len in 1..=5 {
                for old_bits in 0..(1 << old_len) {
                    for new_bits in 0..(1 << new_len) {
                        let old_occurrences = [SentenceOccurrence {
                            tokens: sequence(old_len, old_bits),
                            ..local_fragment_parent("placeholder words", 1, 1)
                        }];
                        let new_occurrences = [SentenceOccurrence {
                            tokens: sequence(new_len, new_bits),
                            ..local_fragment_parent("placeholder words", 2, 2)
                        }];
                        let old_fragments = [test_length_aware_fragment(
                            0,
                            &old_occurrences[0],
                            LocalFragmentOrientation::Prefix,
                            0..old_len,
                        )];
                        let new_fragments = [test_length_aware_fragment(
                            0,
                            &new_occurrences[0],
                            LocalFragmentOrientation::Prefix,
                            0..new_len,
                        )];
                        let mut budget = FlatExactBoundaryBudget::new(
                            FlatExactBoundaryLimits::for_tokens(1_000_000).expect("limits fit"),
                        );
                        let classes = build_flat_exact_boundary_classes(
                            &old_fragments,
                            &new_fragments,
                            &old_occurrences,
                            &new_occurrences,
                            &mut budget,
                        )
                        .expect("flat classes build");
                        let actual = flat_exact_boundary_certification(
                            0,
                            0,
                            &old_fragments,
                            &new_fragments,
                            &classes,
                        )
                        .expect("certification succeeds")
                        .map(|(certification, _)| certification);
                        let depth = sentence_edge_signature_depth(old_len.min(new_len))
                            .expect("depth fits");
                        let old_tokens = &old_occurrences[0].tokens;
                        let new_tokens = &new_occurrences[0].tokens;
                        let prefix = old_tokens[..depth] == new_tokens[..depth];
                        let suffix = old_tokens[old_len - depth..] == new_tokens[new_len - depth..];
                        let expected = match (prefix, suffix) {
                            (true, true) => Some(ExactBoundaryCertification::Both),
                            (true, false) => Some(ExactBoundaryCertification::Prefix),
                            (false, true) => Some(ExactBoundaryCertification::Suffix),
                            (false, false) => None,
                        };
                        assert_eq!(actual, expected);
                        if let Some(certification) = actual {
                            let mut legacy_budget = LengthAwareBudget::new(length_aware_limits());
                            let mut legacy_work =
                                LocalFragmentRecheckReuseWorkAttribution::default();
                            let legacy = length_aware_threshold_capped_edge_recheck_with_cost(
                                &old_fragments[0],
                                &new_fragments[0],
                                &old_occurrences,
                                &new_occurrences,
                                &mut legacy_budget,
                                &mut legacy_work,
                                LocalFragmentCandidateMembership::LengthAwareOnly,
                            )
                            .expect("legacy exact recheck");
                            let ranks = ExactBoundaryRanks::new(
                                &classes.offsets,
                                &classes.prefix_class_ids,
                                &classes.suffix_class_ids,
                            )
                            .expect("flat exact ranks");
                            let mut exact_budget = FlatExactBoundaryBudget::new(
                                FlatExactBoundaryLimits::for_tokens(1_000_000).expect("limits fit"),
                            );
                            let exact = flat_exact_threshold_capped_edge_recheck(
                                0,
                                0,
                                &old_fragments,
                                &new_fragments,
                                &ranks,
                                certification,
                                depth,
                                &mut exact_budget,
                            )
                            .expect("rank exact recheck");
                            assert_eq!(exact.retained, legacy.retained);
                            assert_eq!(exact.avoided_comparisons, legacy.comparisons);
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn flat_exact_boundary_limits_stop_atomically() {
        let documents = || {
            (
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 1, 1)],
                vec![local_fragment_parent("abcdefghijklmnopqrst tail", 2, 2)],
            )
        };
        for (expected, mutate) in [
            (
                LocalFragmentFlatExactBoundaryStopReason::ClassSlotLimit,
                (|limits: &mut FlatExactBoundaryLimits| limits.class_slots = 0)
                    as fn(&mut FlatExactBoundaryLimits),
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::RadixWorkLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.radix_work = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::EstimatedByteLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.common.estimated_bytes = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::ExactRankComparisonLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.exact_rank_comparisons = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::ExactJoinPostingLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.exact_join.postings = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::ExactJoinIntersectionLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.exact_join.intersections = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::ExactJoinAdmissionLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.exact_join.admissions = 0,
            ),
            (
                LocalFragmentFlatExactBoundaryStopReason::ExactJoinSortLimit,
                |limits: &mut FlatExactBoundaryLimits| limits.exact_join.sort_items = 0,
            ),
        ] {
            let mut limits = FlatExactBoundaryLimits::for_tokens(1_000_000).expect("limits fit");
            mutate(&mut limits);
            let (old, new) = documents();
            let flat = flat_exact_boundary_analysis_metrics(old, new, 8, limits);
            assert!(!flat.complete);
            assert_eq!(flat.stop_reason, Some(expected));
            assert_eq!(flat.old_fragments, 0);
            assert_eq!(flat.class_slots, 0);
            assert_eq!(flat.hash_candidates, 0);
            assert_eq!(flat.certification_fingerprint, [0; 32]);
            assert_eq!(flat.retained_fingerprint, [0; 32]);
        }
        assert!(FlatExactBoundaryLimits::for_tokens(usize::MAX).is_none());
    }

    #[test]
    fn certified_boundary_scan_matches_full_scan_exhaustively() {
        let sequence = |length: usize, bits: usize| {
            (0..length)
                .map(|offset| {
                    SentenceEvidenceToken::Scalar(if bits & (1 << offset) == 0 { 'a' } else { 'b' })
                })
                .collect::<Vec<_>>()
        };
        for old_len in 1..=7 {
            for new_len in 1..=7 {
                for old_bits in 0..(1 << old_len) {
                    for new_bits in 0..(1 << new_len) {
                        let old_occurrences = [SentenceOccurrence {
                            tokens: sequence(old_len, old_bits),
                            ..local_fragment_parent("placeholder words", 1, 1)
                        }];
                        let new_occurrences = [SentenceOccurrence {
                            tokens: sequence(new_len, new_bits),
                            ..local_fragment_parent("placeholder words", 2, 2)
                        }];
                        let old = test_length_aware_fragment(
                            0,
                            &old_occurrences[0],
                            LocalFragmentOrientation::Prefix,
                            0..old_len,
                        );
                        let new = test_length_aware_fragment(
                            0,
                            &new_occurrences[0],
                            LocalFragmentOrientation::Prefix,
                            0..new_len,
                        );
                        let mut trie_budget = LengthAwareBudget::new(length_aware_limits());
                        let mut trie = ExactBoundaryTrie::new(&mut trie_budget).expect("trie root");
                        let old_nodes = build_exact_fragment_boundary_nodes(
                            std::slice::from_ref(&old),
                            &old_occurrences,
                            &mut trie,
                            &mut trie_budget,
                        )
                        .expect("old exact nodes");
                        let new_nodes = build_exact_fragment_boundary_nodes(
                            std::slice::from_ref(&new),
                            &new_occurrences,
                            &mut trie,
                            &mut trie_budget,
                        )
                        .expect("new exact nodes");
                        let Some((certification, depth)) =
                            exact_boundary_certification(&old, &new, &old_nodes[0], &new_nodes[0])
                                .expect("certification succeeds")
                        else {
                            continue;
                        };
                        let mut full_budget = LengthAwareBudget::new(length_aware_limits());
                        let mut full_work = LocalFragmentRecheckReuseWorkAttribution::default();
                        let legacy = length_aware_threshold_capped_edge_recheck_with_cost(
                            &old,
                            &new,
                            &old_occurrences,
                            &new_occurrences,
                            &mut full_budget,
                            &mut full_work,
                            LocalFragmentCandidateMembership::LengthAwareOnly,
                        )
                        .expect("legacy recheck succeeds");
                        let mut certified_budget = LengthAwareBudget::new(length_aware_limits());
                        let certified = certified_threshold_capped_edge_recheck(
                            &old,
                            &new,
                            &old_occurrences,
                            &new_occurrences,
                            certification,
                            depth,
                            &mut certified_budget,
                        )
                        .expect("certified recheck succeeds");
                        assert_eq!(certified.retained, legacy.retained);
                        assert_eq!(certified.credited_tokens, certified.avoided_comparisons);
                        assert_eq!(
                            legacy.comparisons,
                            certified.comparisons + certified.avoided_comparisons
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn edge_threshold_required_matches_agrees_with_basis_points() {
        for shorter in 1..=4_096 {
            let required = edge_threshold_required_matches(shorter).expect("threshold fits");
            assert!(
                basis_points(required, shorter)
                    .is_some_and(|score| score >= MIN_WORD_SCORE_EDGE_EVIDENCE)
            );
            assert!(
                required == 0
                    || basis_points(required - 1, shorter)
                        .is_some_and(|score| score < MIN_WORD_SCORE_EDGE_EVIDENCE)
            );
        }
        assert_eq!(basis_points(2_999, 10_000), Some(2_999));
        assert_eq!(basis_points(3_000, 10_000), Some(3_000));
        assert_eq!(edge_threshold_required_matches(10_000), Ok(3_000));
    }

    #[test]
    fn flat_exact_ranks_preserve_the_three_thousand_basis_point_boundary() {
        let tokens = |shared: usize| {
            (0..10_000)
                .map(|index| SentenceEvidenceToken::Scalar(if index < shared { 'a' } else { 'b' }))
                .collect::<Vec<_>>()
        };
        let old_occurrences = [SentenceOccurrence {
            tokens: vec![SentenceEvidenceToken::Scalar('a'); 10_000],
            ..local_fragment_parent("placeholder words", 1, 1)
        }];
        let new_occurrences = [
            SentenceOccurrence {
                tokens: tokens(2_999),
                ..local_fragment_parent("placeholder words", 2, 2)
            },
            SentenceOccurrence {
                tokens: tokens(3_000),
                ..local_fragment_parent("placeholder words", 3, 3)
            },
        ];
        let old_fragments = [test_length_aware_fragment(
            0,
            &old_occurrences[0],
            LocalFragmentOrientation::Prefix,
            0..10_000,
        )];
        let new_fragments = [
            test_length_aware_fragment(
                0,
                &new_occurrences[0],
                LocalFragmentOrientation::Prefix,
                0..10_000,
            ),
            test_length_aware_fragment(
                1,
                &new_occurrences[1],
                LocalFragmentOrientation::Prefix,
                0..10_000,
            ),
        ];
        let mut budget = FlatExactBoundaryBudget::new(
            FlatExactBoundaryLimits::for_tokens(1_000_000).expect("limits fit"),
        );
        let classes = build_flat_exact_boundary_classes(
            &old_fragments,
            &new_fragments,
            &old_occurrences,
            &new_occurrences,
            &mut budget,
        )
        .expect("flat classes build");
        let ranks = ExactBoundaryRanks::new(
            &classes.offsets,
            &classes.prefix_class_ids,
            &classes.suffix_class_ids,
        )
        .expect("flat exact ranks");
        let depth = sentence_edge_signature_depth(10_000).expect("depth fits");
        for (new_index, retained) in [(0, false), (1, true)] {
            let certification = flat_exact_boundary_certification(
                0,
                new_index,
                &old_fragments,
                &new_fragments,
                &classes,
            )
            .expect("certification succeeds")
            .expect("prefix is exact through signature depth")
            .0;
            let recheck = flat_exact_threshold_capped_edge_recheck(
                0,
                new_index,
                &old_fragments,
                &new_fragments,
                &ranks,
                certification,
                depth,
                &mut budget,
            )
            .expect("rank recheck succeeds");
            assert_eq!(recheck.retained, retained);
        }
    }

