    #[test]
    fn local_fragment_shadow_finds_sp_shaped_suffix_comma_deletion() {
        let old = local_fragment_parent("  toolkitrequirement,", 1, 63);
        let new = local_fragment_parent("           toolkitrequirement", 2, 75);
        let metrics = local_fragment_analysis(
            vec![old],
            vec![new],
            LocalFragmentLimits::for_tokens(10_000, 8).expect("limits fit"),
        )
        .expect("shadow completes");

        assert!(metrics.complete);
        assert_eq!(metrics.min_tokens, 8);
        assert_eq!(metrics.signature_depth, 2);
        assert!(metrics.parent_candidate_pairs >= 1);
        let fragments = metrics.old_prefix_fragments
            + metrics.old_suffix_fragments
            + metrics.new_prefix_fragments
            + metrics.new_suffix_fragments;
        assert_eq!(
            metrics.work.signature_token_steps_examined,
            fragments * metrics.signature_depth * 2
        );
        assert_eq!(
            metrics.work.prefix_edge_comparisons_examined
                + metrics.work.suffix_edge_comparisons_examined
                + metrics.work.word_range_scan_comparisons_examined
                + metrics.work.word_merge_comparisons_examined,
            metrics.work.comparisons_examined
        );
        assert_eq!(
            metrics.work.prefix_edge_comparisons_attempted
                + metrics.work.suffix_edge_comparisons_attempted
                + metrics.work.word_range_scan_comparisons_attempted
                + metrics.work.word_merge_comparisons_attempted,
            metrics.work.comparisons_attempted
        );
        assert_eq!(
            metrics.work.edge_gate_passed_pairs + metrics.work.edge_gate_rejected_pairs,
            metrics.candidate_pairs
        );
        assert!(
            metrics.work.length_aware_signature_necessary_pairs
                >= metrics.work.edge_gate_passed_pairs
        );
        assert!(metrics.work.word_range_scan_comparisons_examined > 0);
        assert!(metrics.work.word_merge_comparisons_examined > 0);
        let best = metrics
            .best_sampled_suffix_nonexact_pair
            .expect("suffix non-exact pair exists");
        assert_eq!(best.orientation, LocalFragmentOrientation::Suffix);
        assert_eq!(best.old.token_start, 2);
        assert_eq!(best.new.token_start, 11);
        assert_eq!(best.score, 10_000);
        assert_eq!(best.old_changed_tokens, 1);
        assert_eq!(best.new_changed_tokens, 0);
        assert_eq!(best.edit_distance, 1);
        assert!(metrics.edit_distance_sampled_pairs >= 1);
        assert_eq!(
            metrics.edit_distance_available_pairs + metrics.edit_distance_skipped_pairs,
            metrics.edit_distance_sampled_pairs
        );
        assert!(metrics.work.output_examined >= 1);
    }

